const evidenceSourceTemplates = [
  ["《诊断学》","病史采集与症状学","相关专科指南"],
  ["《诊断学》","体格检查基本方法","相关专科指南"],
  ["《医学影像学》","实验诊断学","影像检查相关指南"],
  ["《内科学》","临床诊断思维","相关专科指南"],
  ["《内科学》","治疗学与患者安全","诊疗规范 / 临床指南"]
];

function evidenceBinding(caseIndex, stageIndex){
  const c=caseLibrary[caseIndex], names=evidenceSourceTemplates[stageIndex];
  return {
    id:`${c.code.replace(' ','-')}-S${stageIndex+1}-FB-001`,
    stage:stageNames[stageIndex],
    references:names.map((title,index)=>({
      id:`REF-${caseIndex+1}${stageIndex+1}${index+1}`,
      title,
      locator:index===2?`${c.specialty}相关条目（指南名称、版本与条目号待临床教师核验）`:`${stageNames[stageIndex]}相关章节（章次待临床教师核验）`,
      status:"待临床教师核验"
    }))
  };
}

